cd /Users/kristinarash/.claude/jobs/802ea68a/tmp; cat > app.py <<'EOF'
import json,sys
d=json.load(open('audit.json'))['result']
order={'critical':0,'high':1,'medium':2,'low':3}
rows=[]
for r in d['domains']+[d['gaps']]:
    v={x['id']:x for x in r.get('verdicts',[])}
    for f in r['findings']:
        vv=v.get(f['id']); sev=f['severity']
        if vv and vv['verdict']=='downgrade' and vv.get('corrected_severity'): sev=vv['corrected_severity']
        if vv and vv['verdict']=='refuted': sev='refuted'
        rows.append((r['domain'],f,vv,sev))
out=['# System audit 2026-10-22 — full findings','','Generated from workflow run wf_11aed943-145 (read-only). Severity shown is after the skeptic pass. Secret values are never shown.','']
out.append('## Domain verdicts\n')
for r in d['domains']+[d['gaps']]:
    out.append(f"**{r['domain']}** — {r['summary']}\n")
    if r.get('not_checked'): out.append('Not checked: '+'; '.join(r['not_checked'])+'\n')
for s in ['critical','high','medium','low','refuted']:
    sel=[x for x in rows if x[3]==s]
    if not sel: continue
    out.append(f'\n## {s.upper()} ({len(sel)})\n')
    for dom,f,vv,_ in sel:
        out.append(f"### {f['id']} — {f['title']}")
        out.append(f"- Domain: {dom} · Effort: {f['effort']} · Already known: {'yes — '+f.get('known_where','') if f['already_known'] else 'no'}")
        if vv: out.append(f"- Skeptic: **{vv['verdict']}**{' → '+vv.get('corrected_severity','') if vv.get('corrected_severity') else ''}. {vv['reason']}")
        out.append(f"- Evidence: {f['evidence']}")
        out.append(f"- Impact: {f['impact']}")
        out.append(f"- Fix: {f['fix']}\n")
open(sys.argv[1],'w').write('\n'.join(out))
from collections import Counter; print(Counter(x[3] for x in rows))
EOF
